//! Double bipoles (manual 4.12) and electro-mechanical devices (4.13): each a node shape; a
//! transformer's coils follow the `inductor` setting, and `quadpoles style=inline` draws them
//! narrower: the variants `transformer|inductor=american|quadpoles style=inline`. Each is measured
//! too with each of its sizes changed (`transformer@width`) and the pairs of them that change it
//! together, and drawn in between.
//!
//! Measured on what CircuiTikZ 1.8.7 draws (`tools/oracle/`), at the default size, in
//! `bipoles/length`; the text goes above them (in the middle of an `elmech`) and does not count in
//! the picture's size.

